const defs=`<defs><pattern id="hazard" width="18" height="12" patternUnits="userSpaceOnUse"><rect width="18" height="12" fill="#ffcf66"/><path d="M-6 12 6 0h8L2 12m10 0L24 0h8L20 12" fill="#152530"/></pattern><linearGradient id="floor" x2=".4" y2="1"><stop stop-color="#315364"/><stop offset="1" stop-color="#1a3545"/></linearGradient><linearGradient id="block" x2=".7" y2="1"><stop stop-color="#4b7186"/><stop offset="1" stop-color="#223d52"/></linearGradient><linearGradient id="gold" x2=".6" y2="1"><stop stop-color="#fff19a"/><stop offset=".35" stop-color="#ffca50"/><stop offset="1" stop-color="#ee8427"/></linearGradient><linearGradient id="shell" x2=".7" y2="1"><stop stop-color="#ffdd7d"/><stop offset=".45" stop-color="#ffb13b"/><stop offset="1" stop-color="#df6d1d"/></linearGradient><linearGradient id="glass" x2=".7" y2="1"><stop stop-color="#16374b"/><stop offset="1" stop-color="#071724"/></linearGradient><filter id="bloom" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="7"/></filter><filter id="shadow" x="-40%" y="-40%" width="180%" height="200%"><feDropShadow dx="0" dy="7" stdDeviation="5" flood-opacity=".35"/></filter><pattern id="grain" width="12" height="12" patternUnits="userSpaceOnUse"><circle cx="3" cy="4" r=".5" fill="#b6e1f2" opacity=".12"/></pattern></defs>`;

function robotArt(){
const side=facing==='L'||facing==='R',back=facing==='U';
const leg=(name,x)=>`<g class="limb leg-${name}" style="--joint-x:${x}px;--joint-y:15px"><path d="M${x} 13v15" stroke="#0b2533" stroke-width="13" stroke-linecap="round"/><path d="M${x} 14v11" stroke="#f4a438" stroke-width="7"/><path d="M${x-5} 31h13" stroke="#a2c9d2" stroke-width="7" stroke-linecap="round"/></g>`;
const arm=(name,x)=>`<g class="limb arm-${name}" style="--joint-x:${x}px;--joint-y:3px"><path d="M${x} 3l${x<0?-8:8} 13" stroke="#102c3a" stroke-width="11" stroke-linecap="round"/><path d="M${x} 3l${x<0?-8:8} 11" stroke="#ffc05a" stroke-width="6" stroke-linecap="round"/></g>`;
return `<ellipse class="ground-shadow" cy="35" rx="29" ry="8" fill="#04131b" opacity=".5"/><g class="direction-model" transform="scale(${facing==='L'?-1:1} 1)"><g class="pip-idle" filter="url(#shadow)">${leg('far',side?-6:-12)}${arm('far',side?-12:-21)}<rect x="${side?-17:-19}" y="-3" width="${side?30:38}" height="28" rx="10" fill="url(#shell)" stroke="#172c39" stroke-width="3"/>${back?'<rect x="-12" y="3" width="24" height="16" rx="4" fill="#234858" stroke="#f6d183"/><path d="M-7 8H7m-14 5H7" stroke="#8fb6be" stroke-width="2"/>':side?'<path d="M4 3v14" stroke="#ffe0a0" stroke-width="3"/>':'<path d="M-9 6h18v9H-9z" fill="#19394b"/><circle cy="10" r="3" fill="#8cebdd"/>'}${leg('near',side?6:12)}${arm('near',side?13:21)}<g class="pip-head"><path d="M0-34v-13" stroke="#263b44" stroke-width="4"/><circle cy="-48" r="6" fill="#ffdf77" stroke="#f4a43a" stroke-width="2"/><rect x="${side?-25:-31}" y="-37" width="${side?48:62}" height="46" rx="18" fill="url(#shell)" stroke="#112f3d" stroke-width="3"/><path d="M-18-30Q0-38 16-30" stroke="#ffe8ad" stroke-width="3" fill="none"/>${back?'<rect x="-21" y="-26" width="42" height="23" rx="9" fill="#d8882c" stroke="#ffe09a"/><path d="M-12-19h24m-24 6h24" stroke="#815321" stroke-width="3"/><circle cx="-24" cy="-13" r="3" fill="#d8f2ef"/><circle cx="24" cy="-13" r="3" fill="#d8f2ef"/>':side?'<path d="M6-29h9q13 0 13 15T15 1H6q-6-15 0-30Z" fill="url(#glass)" stroke="#eb952d" stroke-width="2"/><ellipse cx="18" cy="-16" rx="4" ry="7" fill="#7ff0ff"/><path d="M17-5h6" stroke="#8cf2f2" stroke-width="2"/><circle cx="-15" cy="-14" r="9" fill="#346174" stroke="#122d3a" stroke-width="3"/><circle cx="-15" cy="-14" r="5" fill="#76bac6"/>':'<rect x="-24" y="-29" width="48" height="31" rx="13" fill="url(#glass)" stroke="#e88f25" stroke-width="2"/><ellipse cx="-11" cy="-16" rx="4" ry="7" fill="#7ff0ff"/><ellipse cx="11" cy="-16" rx="4" ry="7" fill="#7ff0ff"/><path d="M-5-6q5 6 10 0" fill="none" stroke="#8cf2f2" stroke-width="2.5" stroke-linecap="round"/>'}</g></g></g>`;
}
function wallArt(x,y){return `<g class="barrier" aria-label="Blocked square"><rect x="${x+6}" y="${y+12}" width="88" height="83" rx="8" fill="#030e18" opacity=".7"/><path d="M${x+7} ${y+10}l10-13h66l10 13v69l-10 13h-66l-10-13Z" fill="#12232f" stroke="#edbb61" stroke-width="2"/><path d="M${x+8} ${y+10}l10-13h64l10 13Z" fill="#65808c" stroke="#93a6a9"/><rect x="${x+14}" y="${y+10}" width="72" height="68" rx="5" fill="#425967" stroke="#8a9da3"/><path d="M${x+20} ${y+20}h60v45h-60Z" fill="#243947"/><path d="M${x+39} ${y+30}l22 22m0-22-22 22" stroke="#c2d3d6" stroke-width="7" stroke-linecap="round"/><rect x="${x+14}" y="${y+73}" width="72" height="11" rx="2" fill="url(#hazard)"/>${[20,80].map(dx=>[17,66].map(dy=>`<circle cx="${x+dx}" cy="${y+dy}" r="2" fill="#a3b8be"/>`).join('')).join('')}</g>`}
function buildBoard(){let s=defs+`<path d="M35 63 58 38H560l25 25v481l-25 25H58l-23-25Z" fill="#071c29" stroke="#42616e" stroke-width="2"/><path d="M42 112V72l20-22h80M578 485v52l-20 22h-80" fill="none" stroke="#69baa9" stroke-width="3"/>`;for(let y=0;y<5;y++)for(let x=0;x<5;x++){const bx=60+x*100,by=50+y*100,wall=levels[level].walls.some(w=>w[0]===x&&w[1]===y);s+=`<g><rect x="${bx+3}" y="${by+6}" width="94" height="94" rx="9" fill="#061923"/><rect x="${bx+3}" y="${by+2}" width="94" height="92" rx="8" fill="url(#${wall?'block':'floor'})" stroke="${wall?'#7496a8':'#456474'}" stroke-width="1.5"/><rect x="${bx+4}" y="${by+3}" width="92" height="90" rx="8" fill="url(#grain)"/>${wall?wallArt(bx,by):''}</g>`}for(let n=0;n<5;n++)s+=`<text x="${110+n*100}" y="31" text-anchor="middle" fill="#7f9eac" font-size="10" font-family="monospace">${'ABCDE'[n]}</text><text x="19" y="${105+n*100}" fill="#7f9eac" font-size="10" font-family="monospace">${n+1}</text>`;s+=`<rect x="72" y="462" width="76" height="76" rx="10" fill="#5bf2ce" opacity=".09" stroke="#90ffe4" stroke-dasharray="4 5"/><g class="portal-rays" stroke="#ffe49a" opacity=".4">${Array.from({length:12},(_,i)=>`<path d="M510 48v-14" transform="rotate(${i*30} 510 100)"/>`).join('')}</g><rect x="474" y="62" width="72" height="78" rx="14" fill="#ffcb61" filter="url(#bloom)" opacity=".45"/><rect x="474" y="62" width="72" height="78" rx="14" fill="#66582a" stroke="#f7d879" stroke-width="3"/><rect x="481" y="69" width="58" height="64" rx="9" fill="#1a3c39" stroke="#c3ac55"/><path class="portal-star" d="m510 77 7 14 16 3-12 11 3 17-14-8-14 8 3-17-12-11 16-3Z" fill="url(#gold)" stroke="#fff3b1" stroke-width="2"/><g id="collectibles"></g><g id="trail"></g><g id="pip" class="robot-position">${robotArt()}</g>`;$('#board').innerHTML=s;draw()}
